// --- Utilidades comunes de EventPass ------------------------------------
const ahora = () => new Date().toISOString();
const nuevoId = (prefijo) =>
  prefijo + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const norm = (v) => String(v ?? '').trim();
const normEmail = (v) => norm(v).toLowerCase();
// Lee todas las filas de un nodo de Google Sheets ignorando el item vacío que produce "Always Output Data".
const filas = (nodo) => {
  try {
    return $(nodo).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
};
const fallo = (status, mensaje, extra = {}) => [{ json: { ok: false, status, body: { ok: false, error: mensaje }, ...extra } }];
const t = $('Chat Trigger').first().json;
const meta = t.metadata || {};
const sesion = norm(t.sessionId);
const usuario_id = norm(meta.usuario_id || t.usuario_id).slice(0, 40);
const visitor_id = norm(meta.visitor_id || t.visitor_id || sesion).slice(0, 64) || 'anonimo';
// La web envía como sessionId el conversation_id que n8n le devolvió; si no existe, se genera uno nuevo.
const existente = filas('Leer Conversaciones').find((c) => c.conversation_id === sesion && c.estado === 'ABIERTA');
const fecha = ahora();
const conversacion = existente
  ? { ...existente, usuario_id: usuario_id || existente.usuario_id, fecha_ultima_interaccion: fecha }
  : { conversation_id: nuevoId('CONV'), usuario_id, visitor_id, fecha_inicio: fecha, fecha_ultima_interaccion: fecha, estado: 'ABIERTA' };
return [{ json: { ...conversacion, nueva: !existente, mensaje: norm(t.chatInput).slice(0, 2000) } }];

