// --- Utilidades de eventos e inscripciones ------------------------------
const ZONA_HORARIA = '-05:00'; // Hora de Colombia
function inicioEvento(evento) {
  const [h = '00', m = '00'] = norm(evento.hora).split(':');
  return new Date(`${norm(evento.fecha)}T${h.padStart(2, '0')}:${m.padStart(2, '0')}:00${ZONA_HORARIA}`);
}
const ESTADOS_ACTIVOS = ['CONFIRMADA', 'LISTA_ESPERA'];
function confirmadasDe(inscripciones, eventoId) {
  return inscripciones.filter((i) => i.evento_id === eventoId && i.estado === 'CONFIRMADA').length;
}
function listaEsperaDe(inscripciones, eventoId) {
  return inscripciones
    .filter((i) => i.evento_id === eventoId && i.estado === 'LISTA_ESPERA')
    .sort((a, b) => norm(a.fecha_inscripcion).localeCompare(norm(b.fecha_inscripcion)));
}
const fechaLegible = (evento) => {
  const d = inicioEvento(evento);
  if (isNaN(d)) return `${evento.fecha} ${evento.hora}`;
  return d.toLocaleString('es-CO', {
    timeZone: 'America/Bogota', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
  });
};
const SISTEMA = "Eres EventPass Assistant, el asistente de soporte de EventPass, una agenda de eventos deportivos en Colombia\n(natación, atletismo, ciclismo, karate y CrossFit, con eventos para adultos y para niños).\n\nResponde en español, en tono cercano y claro, con respuestas breves (máximo 6 frases o una lista corta).\n\nPuedes ayudar con:\n- Eventos: fechas, horas, lugares, disciplinas, grupo de edad, cupos disponibles y estado.\n- Cómo funciona EventPass: registro, inicio de sesión, perfil, inscripción y cancelación (explicando los pasos en la web).\n- Lista de espera: si un evento está lleno, la inscripción queda en LISTA_ESPERA; cuando alguien cancela, cada pocos\n  minutos el sistema asigna el cupo a quien lleva más tiempo esperando y le avisa por correo y Telegram.\n- Vinculación con Telegram: en el perfil se genera un código de 6 caracteres que dura 10 minutos y se envía al bot\n  como /vincular CODIGO. Es obligatorio tener Telegram vinculado para inscribirse.\n- Estados de inscripción: CONFIRMADA (tiene cupo), LISTA_ESPERA (esperando cupo), CANCELADA.\n- Estados de evento: PUBLICADO (abierto), CERRADO (inscripciones cerradas), CANCELADO (no se realizará).\n- Recordatorios: se envían 24 horas y 2 horas antes del evento a quienes tienen cupo confirmado.\n\nReglas estrictas:\n- Eres solo informativo. NO puedes crear cuentas, iniciar sesión, inscribir, cancelar, cambiar cupos, modificar eventos\n  ni cambiar ningún estado. Si te lo piden, explica que no puedes hacerlo y di exactamente dónde hacerlo en la web.\n- Usa solo la información de eventos de abajo. Si algo no aparece ahí, dilo y no lo inventes.\n- Nunca pidas ni repitas contraseñas, tokens o códigos de vinculación.\n- No des información personal de otros usuarios.";
const inscripciones = filas('Leer Inscripciones (solo lectura)');
const lineas = filas('Leer Eventos (solo lectura)')
  .filter((e) => e.evento_id && e.estado !== 'BORRADOR')
  .sort((a, b) => inicioEvento(a) - inicioEvento(b))
  .map((e) => {
    const cupos = Math.max(0, (Number(e.capacidad) || 0) - confirmadasDe(inscripciones, e.evento_id));
    const pasado = inicioEvento(e).getTime() <= Date.now();
    const estado = pasado && e.estado === 'PUBLICADO' ? 'FINALIZADO' : e.estado;
    return `- ${e.nombre} | ${e.categoria} | ${e.grupo_edad} | ${fechaLegible(e)} | ${e.lugar} | estado ${estado}`
      + (e.motivo_estado ? ` (motivo: ${e.motivo_estado})` : '')
      + ` | cupos ${cupos} de ${e.capacidad}, ${listaEsperaDe(inscripciones, e.evento_id).length} en espera`;
  });
const hoy = new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
return [{ json: {
  chatInput: $('Identificar conversación').first().json.mensaje,
  system: `${SISTEMA}\n\nFecha y hora actual en Colombia: ${hoy}.\n\nEventos (datos de solo lectura):\n${lineas.join('\n') || 'No hay eventos publicados.'}`,
} }];

